#include <cstdio>
#include <cstring>

int main() {
    int count = 0, t = 0, n, m, i;
    char a[10000];
    std::scanf("%s", a);
    m = std::strlen(a);
    for (i = 0; i < m && m != 1; i++) {
        if (a[i] <= 92)
            count++;
    }
    for (i = 1; i < m; i++) {
        if (a[0] > 92) {
            if (a[i] <= 92)
                t++;
        }
    }

    if (m == 1) {
        if (a[0] <= 92)
            a[0] = a[0] + 32;
        else
            a[0] = a[0] - 32;
    } else if (count == m) {
        for (i = 0; i < m; i++) {
            a[i] += 32;
        }
    } else if (t == m - 1) {
        a[0] = a[0] - 32;
        for (i = 1; i < m; i++) {
            a[i] = a[i] + 32;
        }
    }

    for (i = 0; i < m; i++) {
        std::printf("%c", a[i]);
    }
    return 0;
}

#include <iostream>
#include <string>
#include <cctype>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string a;
    std::cin >> a;
    int m = a.length();

    if (m == 1) {
        if (std::isupper(a[0])) a[0] = std::tolower(a[0]);
        else a[0] = std::toupper(a[0]);
    } else {
        bool all_upper = true;
        for (char c : a) {
            if (!std::isupper(c)) {
                all_upper = false;
                break;
            }
        }

        bool first_lower_rest_upper = std::islower(a[0]);
        if (first_lower_rest_upper) {
            for (int i = 1; i < m; ++i) {
                if (!std::isupper(a[i])) {
                    first_lower_rest_upper = false;
                    break;
                }
            }
        }

        if (all_upper) {
            for (char &c : a) c = std::tolower(c);
        } else if (first_lower_rest_upper) {
            a[0] = std::toupper(a[0]);
            for (int i = 1; i < m; ++i) a[i] = std::tolower(a[i]);
        }
    }

    std::cout << a;
    return 0;
}

